#include <stdio.h>
#include <string.h>

typedef struct Handler {
    int (*handle)(struct Handler *self, char *req);
    struct Handler *next;
} Handler;

int logging(Handler *self, char *req) {
    printf("Logging: %s\n", req);
    if (self->next) return self->next->handle(self->next, req);
    return 1;
}

int auth_check(Handler *self, char *req) {
    if (strstr(req, "token") == NULL) { printf("Auth: denied\n"); return 0; }
    printf("Auth: ok\n");
    if (self->next) return self->next->handle(self->next, req);
    return 1;
}

int final_handler(Handler *self, char *req) {
    printf("Processed: %s\n", req);
    return 1;
}

int main() {
    Handler h3 = {final_handler, NULL};
    Handler h2 = {auth_check, &h3};
    Handler h1 = {logging, &h2};
    h1.handle(&h1, "GET /data token=abc");
    return 0;
}
